<script setup lang="ts">import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api}from'../../api';import ProductCard from'../../components/ProductCard.vue';import{useCartStore}from'../../stores/cart';import{useSessionStore}from'../../stores/session';import type{Category,Product}from'../../types';const cart=useCartStore();const campus=ref('湖北工业大学'),banners=ref<any[]>([]),categories=ref<Category[]>([]),products=ref<Product[]>([]),loading=ref(true);onShow(async()=>{await useSessionStore().ensureLogin();const home=await api.home();campus.value=home.campus.name;banners.value=home.banners;categories.value=home.categories;products.value=home.hotProducts;await cart.load();loading.value=false});const add=(p:Product)=>cart.set(p,cart.quantity(p.id)+1);const open=(id:string)=>uni.navigateTo({url:`/pages/product/detail?id=${id}`})</script>
<template><view class="page home"><view class="mast"><view><text class="mast__brand">不出寝｜食社</text><text class="mast__slogan">今天不出寝，想吃的照样有</text></view><view class="address"><text class="address__campus">{{campus}}</text><text class="address__room">西区 5 栋 · 612 ›</text></view></view><view class="search" @tap="uni.switchTab({url:'/pages/category/index'})"><text class="search__icon">⌕</text><text class="search__hint">搜零食、饮料、日用品</text><text class="search__action">去找找</text></view><view class="hero" :style="{background:banners[0]?.color||'#ff623e'}"><text class="hero__eyebrow">寝室补给 · 随叫随到</text><text class="hero__title">{{banners[0]?.title||'今天不出寝'}}</text><text class="hero__sub">{{banners[0]?.subtitle||'想吃的照样有'}}</text><text class="hero__badge">{{banners[0]?.badge||'最快 30 分钟到寝'}}</text><view class="hero__shape hero__shape--one"/><view class="hero__shape hero__shape--two"/></view><scroll-view scroll-x class="chips"><view class="chips__inner"><view v-for="item in categories" :key="item.id" class="chip" @tap="uni.switchTab({url:'/pages/category/index'})">{{item.name}}</view></view></scroll-view><view class="promise card"><view><text class="promise__strong">30-60</text><text class="promise__unit">分钟</text><text class="promise__label">立即配送</text></view><view class="promise__line"/><view><text class="promise__strong">2</text><text class="promise__unit">小时</text><text class="promise__label">省心送达</text></view><view class="promise__line"/><view><text class="promise__strong">寝室门口</text><text class="promise__label">楼长送上楼</text></view></view><view class="section-title"><text class="section-title__main">今晚都在买</text><text class="section-title__sub">湖工大热榜</text></view><view v-if="loading" class="skeleton-grid"><view v-for="n in 4" :key="n" class="skeleton"/></view><view v-else class="grid"><ProductCard v-for="p in products" :key="p.id" :product="p" :quantity="cart.quantity(p.id)" @add="add" @open="open"/></view></view></template>
<style scoped lang="scss">@import '../../styles/theme.scss';.home{padding-top:calc(24rpx + env(safe-area-inset-top))}.mast{display:flex;justify-content:space-between;align-items:flex-end}.mast__brand{display:block;font-size:42rpx;font-weight:900;letter-spacing:-2rpx}.mast__slogan{display:block;color:$muted;font-size:21rpx;margin-top:6rpx}.address{text-align:right}.address__campus,.address__room{display:block}.address__campus{font-weight:800;font-size:24rpx}.address__room{color:$primary-dark;font-size:25rpx;margin-top:6rpx}.search{height:88rpx;background:#fff;border:2rpx solid $line;border-radius:30rpx;margin:28rpx 0;display:flex;align-items:center;padding:0 24rpx;box-shadow:0 8rpx 0 rgba(47,38,34,.05)}.search__icon{font-size:42rpx;font-weight:900}.search__hint{color:$muted;margin-left:12rpx;flex:1}.search__action{font-weight:800;color:$primary-dark}.hero{height:330rpx;border-radius:42rpx;padding:42rpx;color:#fff;position:relative;overflow:hidden;box-shadow:0 16rpx 0 #d94327}.hero__eyebrow,.hero__title,.hero__sub,.hero__badge{display:block;position:relative;z-index:2}.hero__eyebrow{font-size:22rpx;font-weight:700;opacity:.85}.hero__title{font-size:58rpx;font-weight:900;margin-top:18rpx;letter-spacing:-3rpx}.hero__sub{font-size:32rpx;font-weight:700;margin-top:4rpx}.hero__badge{display:inline-block;background:$cream;color:$ink;padding:10rpx 20rpx;border-radius:30rpx;margin-top:34rpx;font-size:22rpx;font-weight:800}.hero__shape{position:absolute;border-radius:50%;background:#ffd978}.hero__shape--one{width:230rpx;height:230rpx;right:-30rpx;bottom:-45rpx}.hero__shape--two{width:100rpx;height:100rpx;right:155rpx;top:42rpx;background:#fff;opacity:.22}.chips{margin-top:34rpx;white-space:nowrap}.chips__inner{display:flex;gap:16rpx}.chip{min-width:108rpx;padding:18rpx 26rpx;border-radius:26rpx;background:#fff;border:2rpx solid $line;text-align:center;font-weight:700}.promise{margin-top:28rpx;padding:24rpx;display:flex;align-items:center;justify-content:space-around;text-align:center}.promise__strong,.promise__unit,.promise__label{display:block}.promise__strong{font-size:28rpx;font-weight:900}.promise__unit{font-size:20rpx}.promise__label{font-size:20rpx;color:$muted;margin-top:4rpx}.promise__line{height:56rpx;width:2rpx;background:$line}.grid,.skeleton-grid{display:grid;grid-template-columns:1fr 1fr;gap:22rpx}.skeleton{height:390rpx;border-radius:30rpx;background:linear-gradient(90deg,#f1e7df,#fff,#f1e7df);animation:pulse 1.2s infinite}.skeleton-grid{display:grid}@keyframes pulse{50%{opacity:.55}}</style>
